package ru.nartov.lab6.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import ru.nartov.lab6.dao.StudentDAO;import ru.nartov.lab6.dto.StudentRequest;import ru.nartov.lab6.entity.Student;import ru.nartov.lab6.exception.ResourceNotFoundException;import java.util.List;
@Service @Transactional public class StudentServiceImpl implements StudentService{private final StudentDAO dao;public StudentServiceImpl(StudentDAO d){dao=d;}@Transactional(readOnly=true)public List<Student> findAll(){return dao.findAll();}@Transactional(readOnly=true)public Student findById(Long id){return dao.findById(id).orElseThrow(()->new ResourceNotFoundException("Студент с id="+id+" не найден."));}public Student create(StudentRequest r){return dao.save(new Student(r.getName(),r.getSurname(),r.getFaculty(),r.getAge()));}public Student update(Long id,StudentRequest r){Student s=findById(id);s.setName(r.getName());s.setSurname(r.getSurname());s.setFaculty(r.getFaculty());s.setAge(r.getAge());return dao.save(s);}public void delete(Long id){dao.delete(findById(id));}}
